const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();

const outbound_message_id=Number(input.outbound_message_id??input.message_id??0);
const provider_message_id=text(input.provider_message_id);
const channel=text(input.channel).toLowerCase();
const event_type=text(input.event_type||input.status||'unknown').toLowerCase();
const event_at=text(input.event_at)||new Date().toISOString();
const error_code=text(input.error_code);
const error_message=text(input.error_message);

let raw_event=input.raw_event??input;
try{if(typeof raw_event==='string')raw_event=JSON.parse(raw_event||'{}');}catch{raw_event={raw:raw_event};}

const events=['accepted','sent','delivered','read','failed','undeliverable','rejected','unknown'];
const channels=['whatsapp','sms','email','phone','web_push','in_app'];
const errors=[];

if((!Number.isInteger(outbound_message_id)||outbound_message_id<1)&&!provider_message_id){
  errors.push({field:'message_reference',message:'شناسه داخلی یا Provider Message ID الزامی است.'});
}
if(!channels.includes(channel))errors.push({field:'channel',message:'کانال معتبر نیست.'});
if(!events.includes(event_type))errors.push({field:'event_type',message:'نوع رویداد معتبر نیست.'});
if(Number.isNaN(Date.parse(event_at)))errors.push({field:'event_at',message:'زمان رویداد معتبر نیست.'});

return [{json:{
  outbound_message_id,provider_message_id,channel,event_type,event_at,
  error_code,error_message,raw_event_text:JSON.stringify(raw_event),
  validation_status:errors.length?'invalid':'valid',errors
}}];
